Papers.AnsariRockel2026RhoFootrule.finit.type:
∀ (n : ℕ) (π : Equiv.Perm (Fin (n + 1))),
  have m := Papers.AnsariRockel2026RhoFootrule.rankingDistance n π / (↑n + 1) ^ 2;
  have q := Papers.AnsariRockel2026RhoFootrule.rankingSquare n π / (↑n + 1) ^ 3;
  m ^ 2 + Papers.AnsariRockel2026RhoFootrule.minimumVariance m ≤ q ∧ q ≤ (1 - √(1 - 2 * m) ^ 3) / 3

Papers.AnsariRockel2026RhoFootrule.left_.type:
∀ (S : ProbabilityTheory.Copula.RankRegion.RhoFootrule.LeftData),
  have k := ↑S.N * (↑S.N + 1);
  have ell := 1 / (2 * ↑S.N);
  have delta := k * S.v ^ 2;
  have m := ell - delta;
  Papers.AnsariRockel2026RhoFootrule.upperRho (1 - 3 * m) = 1 - 6 * ell * (2 * m - ell) - 4 * delta * √delta / √k

∀ (S : ProbabilityTheory.Copula.RankRegion.RhoFootrule.LeftData),
  have k := ↑S.N * (↑S.N + 1);
  have delta := k * S.v ^ 2;
  Papers.AnsariRockel2026RhoFootrule.minimumVariance (1 / (2 * ↑S.N) - delta) =
    2 * delta * √delta / (3 * √k) - delta ^ 2

Papers.AnsariRockel2026RhoFootrule.right.type:
∀ (S : ProbabilityTheory.Copula.RankRegion.RhoFootrule.RightData),
  have k := ↑S.N * (↑S.N + 1);
  have ell := 1 / (2 * (↑S.N + 1));
  have delta := k * S.v ^ 2;
  have m := ell + delta;
  Papers.AnsariRockel2026RhoFootrule.upperRho (1 - 3 * m) = 1 - 6 * ell * (2 * m - ell) - 4 * delta * √delta / √k

∀ (S : ProbabilityTheory.Copula.RankRegion.RhoFootrule.RightData),
  have k := ↑S.N * (↑S.N + 1);
  have delta := k * S.v ^ 2;
  Papers.AnsariRockel2026RhoFootrule.minimumVariance (1 / (2 * (↑S.N + 1)) + delta) =
    2 * delta * √delta / (3 * √k) - delta ^ 2

Papers.AnsariRockel2026RhoFootrule.upper.type:
∀ x ∈ Set.Icc 0 1,
  IsGreatest {y | (x, y) ∈ (convexHull ℝ) Papers.AnsariRockel2026RhoFootrule.upperSeeds}
    (Papers.AnsariRockel2026RhoFootrule.upperInnerRatio x)
